from itertools import combinations_with_replacement

dice7 = list(combinations_with_replacement(range(7), 6))
N = len(dice7)

def beats(a, b):
    c = 0
    for x in a:
        for y in b:
            if x > y: c += 1
    return c

# Build adjacency: a -> set of b such that beats(a,b) > 18
print("Building adjacency...")
adj = [[] for _ in range(N)]
for i in range(N):
    for j in range(N):
        if i != j and beats(dice7[i], dice7[j]) > 18:
            adj[i].append(j)
print("done", sum(len(a) for a in adj))

# Find 5-cycle
found = None
for a in range(N):
    for b in adj[a]:
        for c in adj[b]:
            if c == a: continue
            for d in adj[c]:
                if d == a or d == b: continue
                for e in adj[d]:
                    if e == a or e == b or e == c: continue
                    if a in adj[e]:
                        found = (a,b,c,d,e)
                        break
                if found: break
            if found: break
        if found: break
    if found: break

print(found)
if found:
    for x in found:
        print(dice7[x])

dice = [(0, 0, 1, 3, 3, 3),(0, 2, 2, 2, 2, 2),(1, 1, 1, 1, 4, 4),(0, 0, 3, 3, 3, 3),(1, 1, 2, 2, 2, 4)]
def beats(a, b):
    return sum(1 for x in a for y in b if x > y)
for i in range(5):
    print(i, "beats", (i+1)%5, "=", beats(dice[i], dice[(i+1)%5]))
